// MaxEco Node D.2: Load Active Projects from Registers
const fs = require('fs');
const path = require('path');

const testDataPath = path.resolve(process.cwd(), 'automation/data/dummy-finance-registers.json');
let data = {};
if (fs.existsSync(testDataPath)) {
  data = JSON.parse(fs.readFileSync(testDataPath, 'utf8'));
}

return [{ json: data }];

// MaxEco Node D.3: Identify Approaching & Overdue Milestones
// Policy: Zero automated procurement; only internal founder monitoring
const data = $input.first().json;
const solarProjects = data.solarProjects || [];
const itProjects = data.itProjects || [];

const now = new Date();
const todayStr = now.toISOString().slice(0, 10);
const fiveDaysAhead = new Date(now.getTime() + 5 * 86400000).toISOString().slice(0, 10);

const activeMilestones = [];

// 1. Audit Solar Milestones
solarProjects.forEach(p => {
  (p.milestones || []).forEach(m => {
    if (m.status !== 'Completed' && m.dueDate && m.dueDate <= fiveDaysAhead) {
      activeMilestones.push({
        projectType: 'SOLAR',
        projectId: p.id,
        clientName: p.clientName,
        milestone: m.name,
        status: m.status,
        dueDate: m.dueDate,
        isOverdue: m.dueDate < todayStr,
        internalNote: 'Verify site physical condition / APDCL clearance with partner'
      });
    }
  });
});

// 2. Audit IT Milestones
itProjects.forEach(p => {
  (p.milestones || []).forEach(m => {
    if (m.status !== 'Completed' && m.dueDate && m.dueDate <= fiveDaysAhead) {
      activeMilestones.push({
        projectType: 'IT_WEB',
        projectId: p.id,
        clientName: p.clientName,
        milestone: m.name,
        status: m.status,
        dueDate: m.dueDate,
        isOverdue: m.dueDate < todayStr,
        internalNote: 'Review code staging & WhatsApp testing locally before client demo'
      });
    }
  });
});

return activeMilestones.map(m => ({ json: m }));

// MaxEco Node D.4: Write Internal Milestone Action Digest
const fs = require('fs');
const path = require('path');

const items = $input.all().map(i => i.json);
const outDir = path.resolve(process.cwd(), 'docs/reports');
if (!fs.existsSync(outDir)) fs.mkdirSync(outDir, { recursive: true });

const todayStr = new Date().toISOString().slice(0, 10);
let md = '# MaxEco Project Milestone Action Board — ' + todayStr + '\n\n';

if (items.length === 0) {
  md += '✅ All active solar and IT project milestones are on schedule.\n';
} else {
  items.forEach(m => {
    md += '* [' + m.projectType + '] **' + m.clientName + '** (' + m.projectId + '): **' + m.milestone + '**\n';
    md += '  - Status: ' + m.status + ' | Due: **' + m.dueDate + '** ' + (m.isOverdue ? '⚠️ **OVERDUE**' : '') + '\n';
    md += '  - Action: ' + m.internalNote + '\n\n';
  });
}

const outFilePath = path.join(outDir, 'project-milestones-' + todayStr + '.md');
fs.writeFileSync(outFilePath, md, 'utf8');

return [{
  json: {
    status: 'MILESTONES_AUDITED',
    pendingMilestoneCount: items.length,
    reportPath: outFilePath,
    timestamp: new Date().toISOString()
  }
}];
